import numpy as np
X = np.array([[0, 1], [1, 0]], complex); Z = np.diag([1., -1.]).astype(complex)
def op(o, i, n):
    m = np.eye(1)
    for k in range(n): m = np.kron(m, o if k == i else np.eye(2))
    return m
def tfim(n, J, h):
    """Transverse-field Ising chain, open ends: H = -J sum Z_i Z_{i+1} - h sum X_i."""
    return -J * sum(op(Z, i, n) @ op(Z, i + 1, n) for i in range(n - 1)) - h * sum(op(X, i, n) for i in range(n))
n = 8
print(" h/J | ground-state <Z1 Z_n> | gap E1-E0")
for h in (0.2, 0.5, 1.0, 2.0, 5.0):
    E, V = np.linalg.eigh(tfim(n, 1.0, h)); g = V[:, 0]
    corr = np.vdot(g, op(Z, 0, n) @ op(Z, n - 1, n) @ g).real
    print(f" {h:3.1f} | {corr:21.3f} | {E[1] - E[0]:.4f}")
# Spin-flip symmetry: the product of all X commutes with H
P = np.eye(2**n)
for i in range(n): P = P @ op(X, i, n)
H = tfim(n, 1.0, 0.7)
print("[H, X1...Xn] = 0:", np.allclose(H @ P, P @ H))
